#!/usr/bin/env python3
"""Distinct New Westside homepage concepts generated from an editorial grammar."""
from html import escape
PAGES={'homepage-concept-index':('A · Dawn Atlas','atlas'),'homepage-concept-dispatch':('B · Living Current','current'),'homepage-concept-folio':('C · Signal Nocturne','signal')}
CSS=r'''*{box-sizing:border-box}html,body{margin:0;background:var(--paper);color:var(--ink);font-family:"Noto Serif TC",Georgia,serif}body{--paper:#f1eddf;--ink:#15236f;--plate:#d84a31}a{color:inherit;text-decoration:none}.micro{font:700 10px/1.2 ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase}.mast{height:52px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 2.4vw;border-bottom:1px solid var(--ink);position:relative;z-index:5}.mast nav{justify-self:end;display:flex;gap:20px}.mast .zh{justify-self:center;font-size:20px}.bound{outline:1px dashed transparent;outline-offset:3px}.editing .bound:hover{outline-color:var(--plate)}.hero{min-height:88vh;position:relative;overflow:hidden}.display{font:400 clamp(78px,13vw,210px)/.66 "Cormorant Garamond",Georgia,serif;letter-spacing:-.065em;margin:0}.deck{font-size:clamp(18px,1.7vw,29px);line-height:1.48}.plate{color:var(--plate)}.atlas .hero{display:grid;grid-template-columns:7fr 5fr;padding:4vw 2.4vw 3vw}.atlas .hero-copy{align-self:end;position:relative;z-index:2}.atlas .display{max-width:5.5em}.atlas .deck{max-width:22em;margin:2rem 0 0 38%}.atlas-art{position:absolute;width:min(58vw,820px);right:-5vw;top:3vh;color:var(--plate)}.atlas-art .sun{transform-origin:center;animation:turn 34s linear infinite}.atlas .route{stroke-dasharray:8 12;animation:dash 12s linear infinite}.atlas-grid{display:grid;grid-template-columns:repeat(12,1fr);border-top:1px solid var(--ink);border-left:1px solid var(--ink)}.atlas-grid article{min-height:38vh;padding:2.2vw;border-right:1px solid var(--ink);border-bottom:1px solid var(--ink);position:relative;overflow:hidden}.atlas-grid article:first-child{grid-column:span 7}.atlas-grid article:nth-child(2){grid-column:span 5;background:var(--ink);color:var(--paper)}.atlas-grid article:nth-child(n+3){grid-column:span 4}.atlas-grid h2{font:400 clamp(38px,5vw,82px)/.88 "Cormorant Garamond",serif;margin:14vh 0 1rem}.num{font:400 10rem/.7 "Cormorant Garamond",serif;position:absolute;right:-.04em;top:-.08em;opacity:.12}.ticker{overflow:hidden;border-block:1px solid var(--ink);padding:11px 0;white-space:nowrap}.ticker span{display:inline-block;animation:marquee 24s linear infinite}.current{--paper:#e9edcf;--ink:#111;--plate:#08874c}.current .hero{min-height:96vh;display:grid;grid-template-columns:36% 64%;border-bottom:1px solid var(--ink)}.current .rail{padding:3vw 2vw;display:flex;flex-direction:column;justify-content:space-between;border-right:1px solid var(--ink)}.current .rail .display{writing-mode:vertical-rl;transform:rotate(180deg);font-size:clamp(72px,9vw,145px);height:72vh}.current .field{position:relative;padding:4vw;display:flex;align-items:flex-end;overflow:hidden}.current .water{position:absolute;inset:0;color:var(--plate)}.current .field-copy{position:relative;z-index:2;background:var(--paper);border:1px solid var(--ink);padding:2rem;width:min(540px,80%);box-shadow:16px 16px 0 var(--ink)}.current-grid{padding:2vw;display:grid;grid-template-columns:repeat(6,1fr);gap:1rem}.current-grid article{min-height:48vh;background:var(--paper);border:1px solid var(--ink);padding:1.4rem;display:flex;flex-direction:column;justify-content:space-between}.current-grid article:nth-child(1),.current-grid article:nth-child(4){grid-column:span 3}.current-grid article:nth-child(2),.current-grid article:nth-child(3){grid-column:span 3;background:var(--plate);color:var(--paper)}.current-grid article:nth-child(5){grid-column:2/span 4}.current-grid h2{font:400 clamp(42px,5vw,76px)/.9 "Cormorant Garamond",serif;margin:0}.signal{--paper:#071827;--ink:#f0e7cc;--plate:#ff7a39}.signal .mast{border-color:rgba(240,231,204,.3)}.signal .hero{min-height:100vh;display:grid;grid-template-columns:1fr 1.15fr;padding:5vw 3vw}.signal .hero-copy{align-self:center;z-index:2}.signal .deck{max-width:24em;border-left:1px solid var(--plate);padding-left:1.5rem;margin:3rem 0 0 25%}.signal-art{display:grid;place-items:center}.signal-art svg{width:min(48vw,680px);animation:float 7s ease-in-out infinite}.signal-cards{display:grid;grid-template-columns:repeat(2,1fr);border-top:1px solid rgba(240,231,204,.3)}.signal-cards article{min-height:55vh;padding:3vw;border-right:1px solid rgba(240,231,204,.3);border-bottom:1px solid rgba(240,231,204,.3);position:relative}.signal-cards article:nth-child(3){grid-column:span 2;background:var(--ink);color:var(--paper)}.signal-cards h2{font:400 clamp(48px,6vw,96px)/.82 "Cormorant Garamond",serif;margin:22vh 0 1rem}.reveal{opacity:0;transform:translateY(30px);transition:.8s}.reveal.on{opacity:1;transform:none}.progress{position:fixed;left:0;top:0;height:3px;width:100%;transform-origin:left;background:var(--plate);z-index:20}@keyframes turn{to{transform:rotate(360deg)}}@keyframes dash{to{stroke-dashoffset:-200}}@keyframes marquee{to{transform:translateX(-50%)}}@keyframes float{50%{transform:translateY(-18px) rotate(2deg)}}@media(max-width:760px){.mast{grid-template-columns:1fr auto}.mast .zh{display:none}.atlas .hero,.current .hero,.signal .hero{grid-template-columns:1fr}.atlas .deck,.signal .deck{margin-left:0}.atlas-art{opacity:.35;width:100vw}.current .rail .display{writing-mode:initial;transform:none;height:auto}.current-grid,.signal-cards{grid-template-columns:1fr}.current-grid article,.signal-cards article{grid-column:1!important}.signal-art{min-height:55vh}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}}'''
ATLAS='''<svg class="atlas-art" viewBox="0 0 700 700" fill="none"><circle class="sun" cx="350" cy="350" r="270" stroke="currentColor" stroke-width="2"/><circle cx="350" cy="350" r="190" fill="currentColor" opacity=".08"/><path class="route" d="M62 500C180 310 214 540 350 300S570 180 650 58" stroke="currentColor" stroke-width="8"/><path d="M75 540C210 620 420 630 624 470M95 580C255 690 482 640 650 520" stroke="currentColor"/><g fill="currentColor"><circle cx="62" cy="500" r="13"/><circle cx="350" cy="300" r="13"/><circle cx="650" cy="58" r="13"/></g><text x="330" y="365" fill="currentColor" font-size="132" font-family="Georgia">西</text></svg>'''
WATER='''<svg class="water" viewBox="0 0 900 760" preserveAspectRatio="xMidYMid slice"><defs><pattern id="p" width="26" height="26" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r="2" fill="currentColor"/></pattern></defs><rect width="100%" height="100%" fill="url(#p)" opacity=".32"/><path d="M-80 480C130 330 250 660 470 470S750 310 980 430V850H-80Z" fill="currentColor"/><path d="M-80 390C170 240 270 530 510 350S760 250 980 340" fill="none" stroke="#111" stroke-width="16"/></svg>'''
SIGNAL='''<svg viewBox="0 0 700 700"><circle cx="350" cy="350" r="260" fill="none" stroke="currentColor" opacity=".25"/><circle cx="350" cy="350" r="180" fill="none" stroke="currentColor" opacity=".55"/><path d="M350 55L410 295 650 350 410 405 350 645 290 405 50 350 290 295Z" fill="var(--plate)"/><path d="M350 178L385 315 522 350 385 385 350 522 315 385 178 350 315 315Z" fill="var(--paper)"/><circle cx="350" cy="350" r="34" fill="var(--ink)"/></svg>'''
def b(node,field='text',tag='span',cls=''):return f'<{tag} class="bound {cls}" data-node-id="{node}" data-field="{field}"></{tag}>'
def mast():return '<header class="mast"><b class="micro">WESTSIDE WATCH · VAUGHAN / TORONTO</b><b class="zh">西望</b><nav class="micro"><a href="/journal/">Journal</a><a href="https://westsidewatch.github.io/one/">One</a><a href="https://westsidewatch.github.io/join/">Join</a></nav></header>'
def cards(ids,cls):
 labels=['01 / JOURNAL','02 / SCRIPTURE','03 / CHURCH','04 / LIBRARY','05 / THE GATE'];out=[]
 for i,(node,label) in enumerate(zip(ids,labels),1):out.append(f'<article class="reveal"><span class="micro plate">{label}</span><span class="num">{i}</span>{b(node,"title","h2")}{b(node,"body","p","deck")}</article>')
 return f'<section class="{cls}">'+''.join(out)+'</section>'
def render(page_id,edit=False):
 if page_id not in PAGES:raise ValueError('homepage_candidate_not_supported:'+str(page_id))
 name,kind=PAGES[page_id];ids=['journal-tower','one-territory','church-territory','library-territory','join-territory']
 if kind=='atlas':body=f'{mast()}<main class="atlas"><section class="hero">{ATLAS}<div class="hero-copy"><div class="micro plate">NEW WESTSIDE / DAWN ATLAS / 01</div>{b("home-title","text","h1","display")}{b("home-deck","text","p","deck")}</div></section><div class="ticker micro"><span>WATCH · READ · STUDY · GATHER · REMEMBER · WESTSIDE · 西望 · WATCH · READ · STUDY · GATHER · REMEMBER · WESTSIDE · 西望 · </span></div>{cards(ids,"atlas-grid")}</main>'
 elif kind=='current':body=f'{mast()}<main class="current"><section class="hero"><div class="rail"><span class="micro">NEW WESTSIDE / LIVING CURRENT / 02</span>{b("home-title","text","h1","display")}</div><div class="field">{WATER}<div class="field-copy">{b("watch-kicker","text","div","micro plate")}{b("home-deck","text","p","deck")}{b("verse","text","p","micro")}</div></div></section>{cards(ids,"current-grid")}</main>'
 else:body=f'{mast()}<main class="signal"><section class="hero"><div class="hero-copy"><div class="micro plate">NEW WESTSIDE / SIGNAL NOCTURNE / 03</div>{b("home-title","text","h1","display")}{b("home-deck","text","p","deck")}</div><div class="signal-art">{SIGNAL}</div></section>{cards(ids[:3],"signal-cards")}</main>'
 script=f'''<script>(()=>{{const PAGE={page_id!r},edit={str(edit).lower()};let w,p;async function load(){{w=await(await fetch('/api/workspace',{{cache:'no-store'}})).json();p=w.pages.find(x=>x.id===PAGE);document.querySelectorAll('[data-node-id]').forEach(el=>{{let n=p.nodes.find(x=>x.id===el.dataset.nodeId),f=el.dataset.field||'text';if(n&&n[f]!=null)el.textContent=n[f];if(edit){{document.body.classList.add('editing');el.contentEditable='true';el.addEventListener('blur',()=>save(el))}}}});const io=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('on',e.isIntersecting)),{{threshold:.12}});document.querySelectorAll('.reveal').forEach(x=>io.observe(x));parent.postMessage({{type:'dore-ready',page_id:PAGE,revision:w.revision}},'*')}}async function save(el){{let f=el.dataset.field||'text',r=await fetch('/api/workspace',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{op:'set_node',page_id:PAGE,id:el.dataset.nodeId,patch:{{[f]:el.innerText}}}})}});if(r.ok){{w=await r.json();parent.postMessage({{type:'dore-saved',page_id:PAGE,revision:w.revision}},'*')}}}}addEventListener('scroll',()=>document.querySelector('.progress').style.transform='scaleX('+(scrollY/(document.documentElement.scrollHeight-innerHeight)||0)+')',{{passive:true}});load()}})()</script>'''
 return f'<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(name)} · New Westside</title><style>{CSS}.current,.signal{{background:var(--paper);color:var(--ink)}}</style></head><body><div class="progress"></div>{body}{script}</body></html>'
